def search_course_specs(query: str) -> str:
    """
    從 docs/course_specs/ 下的 CH01~CH12 永久課程規格檔中動態檢索與問題最相關的段落，
    確保 App 內建 AI 助教永遠不會遺忘任何一堂課的細節。
    """
    specs_dir = os.path.join(os.path.dirname(os.path.dirname(__file__)), "docs", "course_specs")
    if not os.path.exists(specs_dir):
        return ""

    clean_q = re.sub(r'[？\?！!。，,、\s請問題想問什麼是怎麼如何為何嗎呢的了]', ' ', query).strip()
    tokens = [t for t in clean_q.split() if len(t) >= 2]
    ta_terms = [
        "轉折波", "頭頭高", "底底高", "頭頭低", "底底低", "逃命波", "弱勢回檔", "強勢回檔",
        "變盤線", "晨星", "夜星", "母子", "吞噬", "烏雲罩頂", "旭日東昇", "一日封口", "紡錘", "二分之一", "1/2",
        "扣抵", "葛蘭畢", "多頭排列", "空頭排列", "均線糾結", "黃金交叉", "死亡交叉",
        "基本量", "攻擊量", "爆大量", "止跌量", "換手量", "調節量", "出貨量", "草叢量", "窒息量", "凹洞量", "黃金右腳",
        "六六大順", "特別報價", "淘汰選股", "底部圖形", "獵兔", "鎖股",
        "回後買上漲", "K線橫盤", "頭肩底", "頭肩頂", "三重底", "圓弧底", "一字底", "上升軌道", "下跌軌道", "彈後空", "飆股",
        "停損", "移動停利", "部位管理", "三張", "等幅測距", "套牢", "解套", "主動式ETF", "00981A", "00982A", "00990A", "大盤同步"
    ]
    for term in ta_terms:
        if term.lower() in query.lower() and term not in tokens:
            tokens.append(term)

    if not tokens:
        return ""

    best_score = 0
    best_section = ""
    best_file = ""

    try:
        for fname in sorted(os.listdir(specs_dir)):
            if not fname.endswith(".md") or fname.startswith("00_"):
                continue
            fpath = os.path.join(specs_dir, fname)
            with open(fpath, "r", encoding="utf-8", errors="ignore") as f:
                content = f.read()
            sections = re.split(r'\n(?=##+ )', content)
            for sec in sections:
                if "程式碼" in sec and "對照" in sec:
                    continue
                score = sum(3 if t in sec.splitlines()[0] else 1 for t in tokens if t.lower() in sec.lower())
                if score > best_score and score >= 2:
                    best_score = score
                    best_section = sec.strip()
                    best_file = fname.replace(".md", "")
    except Exception:
        return ""

    if best_section:
        if len(best_section) > 1800:
            best_section = best_section[:1800] + "\n\n...(完整內容請參閱 docs/course_specs/" + best_file + ".md)"
        return f"### 🧑‍🏫 【技術分析全攻略 · 永久課程知識庫精準調閱 ({best_file})】\n\n{best_section}"

    return ""


def answer_general_ta_question(query: str) -> str:
    """
    純觀念或未指定個股的技術分析問題指引
    """
    q = query.strip()
    return f"""### 🧑‍🏫 【技術分析實戰助教 · 觀念指引】
針對您請教的實戰問題：「**{q}**」：

1. **核心技術面把關法則**：
   - **確認大趨勢（六字訣）**：做多先看「頭頭高、底底高」，多頭拉回測線有守才是高勝率買點。
   - **觀察均線（5MA 操盤線）**：買進必須站在 5MA 之上且 5MA 翻揚助漲；跌破 5MA 果斷退場。
   - **量價結構**：攻擊時放量（> 20MA 均量 1.5 倍），拉回整理時量縮。
   - **風控紀律**：跌破 5MA 或虧損達 5% 立即無條件停損保全本金。

💡 **助教貼心提示**：
如果您想請助教診斷**具體某檔股票**（例如想知道目前能不能買、支撐壓力在哪裡），請在問題中附上**股票代號或名稱**（例如：「*請問 2330 目前適合進場嗎？*」或「*請問 2851 在 8/26 為什麼不適合買？*」），助教將立即為您重現該股票的詳細技術面診斷與應對劇本！"""

def diagnose_stock_deeply(code: str, query: str = "", as_of_date: str = None, *args, **kwargs):
    """
    深度診斷股票技術面，支援「歷史覆盤時光機」切片
    """
    df_raw = kwargs.get('df_raw', None)
    info = kwargs.get('info', None)
    if df_raw is None or info is None:
        df_raw, info = fetch_stock_kline(code, period="1y")
    if df_raw is None or df_raw.empty or "error" in info or len(df_raw) < 5:
        return None

    is_replay = False
    target_date_str = as_of_date if as_of_date else extract_date_from_query(query, df_raw)

    if target_date_str:
        target_ts = pd.to_datetime(target_date_str)
        sliced = df_raw[df_raw['Date'] <= target_ts].copy().reset_index(drop=True)
        if not sliced.empty:
            df = sliced
            is_replay = True
        else:
            df = df_raw
    else:
        df = df_raw

    if len(df) < 5:
        return None

    points, lines, highest_peak, lowest_trough = calculate_turning_points(df, ma_period=5)
    trend = analyze_trend(df, points)
    signals_dict, signals_list = detect_signals(df, trend)

    last = df.iloc[-1]
    prev = df.iloc[-2] if len(df) > 1 else last
    c = round(float(last['Close']), 2)
    o = round(float(last['Open']), 2)
    h = round(float(last['High']), 2)
    l = round(float(last['Low']), 2)
    v = float(last['Volume'])
    v_ma20 = float(last['Vol_MA20']) if not np.isnan(last['Vol_MA20']) else v

    sma5 = round(float(last['SMA_5']), 2)
    sma20 = round(float(last['SMA_20']), 2) if not np.isnan(last['SMA_20']) else sma5
    sma60 = round(float(last.get('SMA_60', sma20)), 2)

    # 1. 深度排查：過去 30 天是否有高檔爆量長黑K (主力出貨/套牢賣壓)
    heavy_black_ks = []
    sub30 = df.iloc[-30:] if len(df) >= 30 else df
    for _, r in sub30.iterrows():
        vol = r['Volume']
        vma = r.get('Vol_MA20', 0)
        is_black = (r['Close'] < r['Open']) or ((r['High'] - max(r['Open'], r['Close'])) > (r['High'] - r['Low']) * 0.4)
        if vma > 0 and vol >= vma * 1.6 and is_black:
            ratio = round(vol / vma, 1)
            heavy_black_ks.append({
                "date": r['Date'].strftime('%m/%d'),
                "full_date": r['Date'].strftime('%Y-%m-%d'),
                "high": round(float(r['High']), 2),
                "close": round(float(r['Close']), 2),
                "ratio": ratio
            })

    # 2. 檢測連漲天數 (是否追高)
    up_days = 0
    for k in range(len(df) - 1, max(0, len(df) - 6), -1):
        if df.iloc[k]['Close'] > df.iloc[k - 1]['Close']:
            up_days += 1
        else:
            break

    # 3. 距離前高壓力之獲利空間
    res = trend.get('resistance')
    sup = trend.get('support')
    space_to_res = ((res - c) / c * 100) if (res and res > c) else 0

    # 4. 型態優勢判定
    is_bull = trend.get('higher_highs', False) and trend.get('higher_lows', False)
    is_stand_5ma = c >= sma5
    is_red = c >= o
    is_break_yesterday = (c > float(prev['High']))

    recent_range_max = df.iloc[-8:-1]['High'].max() if len(df) >= 8 else c
    is_range_breakout = c >= recent_range_max * 0.995

    pros = []
    cons = []

    if is_bull:
        pros.append("多頭架構確認（頭頭高 ↗、底底高 ↗）")
    elif trend.get('higher_highs', False):
        pros.append("目前為頭頭高（多頭初升或反彈架構）")

    if is_stand_5ma and is_red:
        pros.append("當日收紅 K 站上 5MA 操盤線，符合短線進場觸發要件")

    if is_range_breakout:
        pros.append("屬於 K 線橫盤整理後的向上突破位置")

    if signals_dict.get('ma_squeeze_breakout', False):
        pros.append("【四線高度糾結突破】四線（5/10/20/60MA）低檔高度糾結後放量長紅第一根突破！操盤心法：糾結突破後面常有倍數大行情，次日若未漲停鎖死，開平或小漲可把握進場！")

    if signals_dict.get('main_wave_2nd', False):
        pros.append("【主升段第二波發動】第一波急漲連噴洗盤守穩月線，今日放量過昨高站上5MA，為第二波飆股主升段起漲點！")

    if signals_dict.get('is_turnover_success', False):
        pros.append("【高檔巨量換手成功】高檔爆大量黑K或變盤線後，3天內強勢長紅過高，籌碼洗淨換手完畢續噴！")

    if signals_dict.get('is_attack_vol', False):
        pros.append("【5MA 攻擊量達標】今日量能達 5MA 基本量 1.25 倍以上，多方主力出量推升！")

    if signals_dict.get('breakout_heavy_black_high', False):
        if signals_dict.get('breakout_heavy_black_high_pos_warning', False):
            pros.append("【突破大量黑K高點】收盤越過前方大量黑K最高點，符合換手轉強進場點（10/22 助教冠西電指引：符合，但位置有點高要注意，採短線操作）")
            cons.append("【高檔位階風險提示】雖符合突破大量黑K進場點，但目前波段位置偏高（10/22 助教冠西電指引：位置有點高要注意，嚴守5MA短線應對）")
        else:
            pros.append("【突破大量黑K高點】收盤實質越過前方大量黑K高點，主力洗盤換手成功再轉強！")

    if signals_dict.get('abc_approaching_cutline', False):
        cons.append("【尚未破切 · 先鎖股等待】今日強勢紅K逼近下降切線但『沒有破切』，尚未完成多頭 ABC 突破（10/22 助教華新科 & Ivan 指引：先鎖股等明天確認破切再進場）")

    if signals_dict.get('deep_pullback_trend_change_warning', False):
        cons.append("【深回檔 / 長上影黑K 趨勢改變警示】雖然位置處於回後買上漲或均線上方，但因前波回檔較深或當日收長上影線黑K，容易趨勢改變，務必注意前高壓力是否能過（10/22 助教 TPK-KY / 川寶指引）")

    if signals_dict.get('breakout_heavy_vol_watch_next', False):
        cons.append("【盤整突破爆量留上影警示】突破伴隨爆大量與上影線，高檔換手劇烈，務必注意次日與後續走勢（10/22 助教晶碩指引）")

    if signals_dict.get('three_days_two_gaps_down_warning', False):
        cons.append("【三天二缺口出貨警訊】多頭回檔以『三天二缺口』方式急跌，空方賣壓傾巢而出，極可能是主力高檔出貨（10/23 助教臻鼎-KY指引）")

    if signals_dict.get('gap_up_then_gap_down_reversal', False):
        cons.append("【向上跳空後又跳空跌回】前波向上跳空後近期又向下跳空回來，提防島狀反轉或 M 頭出貨結構（10/23 助教臻鼎-KY指引）")

    if signals_dict.get('bearish_engulf_to_abc_watch', False):
        cons.append("【長黑吞噬破5均轉盤整 · 鎖股等ABC】今日長黑吞噬跌破 5 均，多頭轉為盤整，短線應先出場；但因股價仍在月線 (20MA) 之上，可列入鎖股池鎖定後續『多頭 ABC 突破』（10/23 助教南亞指引）")

    if signals_dict.get('fake_high_intraday_pierce_only', False):
        cons.append("【盤中過高收盤未過＝假過高】前波或今日僅盤中最高價越過前高、收盤價並未過高（上影線即壓力，壓力未被實質突破）；若未補量收盤站上前高反而跌破 5MA，轉折波看似多頭但實質為『矩形盤整（頭頭低先賣）』（10/25 助教台光電權威指引）")

    if signals_dict.get('kline_consolidation_not_broken_no_short', False):
        cons.append("【K線橫盤還沒跌破 · 非彈後空點】雖碰 5 均後收黑 K，但目前仍處於『K線橫盤』區間內尚未跌破下緣，並非彈後空下跌進場點（10/25 助教旺宏指引）")

    if signals_dict.get('rebound_short_ma20_still_rising_warning', False):
        cons.append("【位置屬彈後空但月線仍向上】結構雖呈頭頭低/破前低之彈後空下跌（多單早該出場），但目前 20MA 月線仍向上、均線尚未空排，做空須留意月線扣抵支撐抵抗（10/25 助教華新科指引）")

    if signals_dict.get('bear_confirm_at_ma60_support_wait_bounce', False):
        cons.append("【空頭急跌剛碰季線/支撐區】目前以急跌方式來到季線（60MA）或前波支撐位置，要看季線/支撐是否有撐，直接追空僅限短線操作；建議等反彈後再做『彈後空下跌』會更穩（10/25 助教金居 & 10/27 指引）")

    if signals_dict.get('left_red_right_black_low_pos_hold', False):
        pros.append("【左長紅右長黑變盤徵兆 · 低位階未破5均續抱觀察】大量紅K後收黑（左長紅右長黑）要注意次日是否跌破5日線；但目前位階不高、未破5均與停損價，在守停損情況下可續抱觀察（10/25 助教美股 PG 寶僑指引）")

    if signals_dict.get('breakout_20ma_falling_stall_warning', False):
        cons.append("【站上20MA但20MA方向向下 · 防隔兩天不漲】雖收紅K站上20日均線，但目前20日均線方向向下，須承受隔天、隔兩天股價不漲的震盪；待20MA方向轉向上才易展開主升段急噴（10/25 林穎老師影片指引）")

    if signals_dict.get('gain_over_10pct_take_profit_alert', False):
        cons.append("【波段漲過一成 · 看訊號準備停利】波段累計漲逾 10%，高檔爆大量長紅覆蓋黑K切忌盲目追價，持有者應提高警覺『看訊號準備停利』（10/29 助教達航指引）")

    if signals_dict.get('box_in_range_warning', False):
        cons.append("【箱型整理區間內震盪 · 建議等帶量突破】目前處於箱型區間內部震盪，在區間操作常一直停損（上漲遇壓、下跌遇撐），建議耐心等待帶量突破區間再切入（10/29 助教群聯指引）")

    if signals_dict.get('rebound_signal_not_entry_warning', False):
        cons.append("【轉折是訊號 · 非進場位置與條件】目前收在月線下或月線下彎，出現晨星/鎚子等轉折線型僅代表跌勢減緩之訊號，絕非做多進場條件，量縮上攻無力切忌摸底（10/29 助教大盤指引）")

    if signals_dict.get('breakout_next_day_shadow_pullback', False):
        pros.append("【長紅突破次日黑K下影線回測】突破長紅次日收黑但帶下影線且守在突破紅K低點之上，黑K可視為健康支撐回測，未破停損續抱（10/29 助教旭隼指引）")

    if signals_dict.get('two_peaks_resistance_alert', False):
        cons.append("【遭遇二個頭部重壓 · 過壓前不操作】正前方緊鄰兩個波峰形成的雙頭套牢反壓，依 10/30 助教華新科/頎邦鐵律『二個頭壓，過壓前這檔是不操作的』，嚴防假突破拉回！")

    if signals_dict.get('low_vol_breakout_vs_pressure_alert', False):
        cons.append("【攻擊量小於壓力量 · 防高點受阻】突破紅K成交量明顯小於前波頭部套牢量，依 10/30 助教百一指引『攻擊量跟壓力量比較，不確定高點是否能到』，需後續補量才能續攻！")

    if signals_dict.get('bottom_volume_better_than_breakout', False):
        pros.append("【底部爆量洗淨後續過高】低檔整理曾爆巨量換手、隨後帶量過高，依 10/30 助教佳世達指引『爆量在低點後續過高，比過高當日爆量更安心』！")

    prev_high = float(prev['High'])
    if signals_dict.get('pullback_buy', False) or (is_stand_5ma and l <= sma5 * 1.02 and c > o):
        if is_break_yesterday:
            pros.append(f"符合『回後買上漲』進場確認（今日收盤 {c:.2f} 元突破前一日高點 {prev_high:.2f} 元，轉折紅 K 攻擊確立）")
        else:
            cons.append(f"處於『回後買上漲觀察位置』，但今日收盤尚未突破前一日高點 ({prev_high:.2f} 元)；依 09/18 助教鐵律：該高點點位固定不變，須等待後續收盤突破前一日高點才算正式進場！")

    # 檢查月線下彎 (09/18 助教鐵律：月線下彎非 ABC 突破，當空頭反彈)
    prev_sma20 = float(df.iloc[-2]['SMA_20']) if len(df) > 1 else sma20
    is_20ma_down = (sma20 < prev_sma20 * 0.999)
    if is_20ma_down and (c < sma20 or (c >= sma20 and not is_bull)):
        cons.append(f"月線 (20MA, {sma20:.2f} 元) 目前仍向下彎助跌；依 09/18 助教鐵律『月線下彎不能算 ABC 突破，只能視為空頭反彈』，上方反壓沉重！")

    if signals_dict.get('ma20_death_break', False):
        cons.append("【趨勢線鐵律】跌破月線已超過 3 天且月線向下彎，多頭徹底終結變空頭，依操盤紀律絕不可逆勢做多，持股應全數清倉！")

    if signals_dict.get('ma_squeeze_breakdown', False) or signals_dict.get('bearish_alignment_4ma', False):
        cons.append("【四線空排空頭警訊】均線糾結後長黑摜破，形成 5MA < 10MA < 20MA < 60MA 四線空排下彎！空方慣性沉重，嚴禁做多！")

    if signals_dict.get('is_false_breakout_dump', False):
        cons.append("【假突破誘多出貨】突破長紅後 3 天內長黑摜破該長紅最低點！主力誘多倒貨陷阱，必跑！")

    if signals_dict.get('is_volume_price_divergence', False):
        cons.append("【量價背離警示】價漲量急縮背離或高檔出量滯漲，多方動能匱乏，慎防拉回倒貨！")

    # 14大淘汰檢核加入缺點清單
    elim_info = signals_dict.get('elimination_info') or {}
    if elim_info.get('is_eliminated', False):
        for r in elim_info.get('reasons', []):
            if r not in cons:
                cons.append(r)

    # 檢查拉回幅度是否過深 (09/18 助教鐵律：正常漲10塊拉回2塊，底平或回撤過深非健康多頭)
    if sup and sup > 0 and abs(l - sup) / sup < 0.015 and not is_bull:
        cons.append(f"拉回幅度過深（低點接近前波底線 {sup:.2f} 元），非健康『漲10回2』的淺幅修正，型態偏向底平或直角三角，慎防轉弱破支撐！")

    # 檢查當日是否本身就是爆量黑K
    is_today_heavy_black = False
    if v_ma20 > 0 and v >= v_ma20 * 1.6 and (c < o or (h - max(o, c)) > (h - l) * 0.4):
        is_today_heavy_black = True
        cons.append(f"當日出現極端爆量長黑 K（成交量為 20 均量 {round(v/v_ma20, 1)} 倍，高點 {h:.2f} 元），主力高檔出貨套牢賣壓沉重！")

    # 檢查前方未化解的爆量黑K
    unresolved_black_ks = [b for b in heavy_black_ks if b['high'] >= c and b['full_date'] != last['Date'].strftime('%Y-%m-%d')]
    if unresolved_black_ks:
        for bk in unresolved_black_ks[-2:]:
            cons.append(f"前方 {bk['date']} 出現極端爆量黑 K（成交量為 20 均量 {bk['ratio']} 倍，高點 {bk['high']} 元），上方存在巨大套牢賣壓")

    if up_days >= 3:
        cons.append(f"股價截至當日已連續上漲 {up_days} 天，短線偏離均線，此時買進屬於追高，容易遇到短線回檔")

    if space_to_res > 0 and space_to_res < 3.0:
        cons.append(f"距離上方前波高點壓力 ({res:.2f} 元) 空間僅剩 {space_to_res:.1f}%，上方肉少骨頭多，風險報酬比不划算")

    # 檢查上方未回補空方跳空缺口反壓 (如 5536 跳空跌停缺口)
    try:
        from core.gap_detector import detect_unfilled_gaps
        gaps_ai = detect_unfilled_gaps(df, lookback_bars=120)
        og_ai = gaps_ai.get("nearest_overhead_gap")
        if og_ai and 0 <= og_ai.get('distance_pct', 99) <= 3.0:
            cons.append(f"上方緊鄰 {og_ai['date_str']} 重大空方跳空缺口反壓 ({og_ai['rem_bottom']:.2f}~{og_ai['rem_top']:.2f} 元，距現價僅 +{og_ai['distance_pct']:.1f}%)，真空套牢賣壓極沉重，嚴防逢高受阻假突破！")
    except Exception:
        pass

    if sma20 < sma60 and c < sma60:
        cons.append("季線 (60MA) 仍位於上方呈下彎壓制，屬於中長線反彈格局而非主升段")

    # 最終決策定調
    if signals_dict.get('is_false_breakout_dump', False):
        decision = "🔴【假突破誘多出貨陷阱，全數出清必跑！】"
        advice_summary = "突破長紅後 3 天內被長黑摜破最低點，主力誘多倒貨確認，多頭陷阱無疑，絕不可心存僥倖，持股必須立即全數出清逃命！"
    elif elim_info.get('eliminated_count', 0) >= 2:
        decision = "🔴【命中 14 大淘汰選股法，嚴禁做多！】"
        advice_summary = f"觸發實戰淘汰條件：{'; '.join(elim_info['reasons'][:2])}。技術面存在重大瑕疵，嚴禁在此摸底做多！"
    elif is_today_heavy_black:
        if is_bull and c >= sma5 and (not sup or l >= sup * 0.99):
            decision = "🟡【高檔爆量黑K但未破5均與底撐 · 趨勢不變先觀察次日】"
            advice_summary = "當日雖開高走低爆出大量長黑K（遭遇線/洗盤疑慮），但收盤仍守穩 5MA 之上且未跌破前波轉折底支撐（注意：前低是指前波轉折底，而非昨日K棒低點）。依 10/22 助教德宏指引：『趨勢不變、支撐沒破，先觀察次日！』惟若前一日高點追進已觸及個人 -5% 停損線者，仍應依 -5% 紀律處理；空手者暫勿躁進，等次日確認止穩或回後買上漲！"
        else:
            decision = "🔴【高檔爆量長黑K，主力出貨警訊，嚴禁買進】"
            advice_summary = "當日爆出巨量長黑，高檔套牢賣壓極度沉重，此為主力出貨典型警訊，嚴禁在此進場摸底，持股者應依紀律嚴格執行防守停損！"
    elif cons:
        if pros:
            decision = "🟡【符合進場型態與位置，但「不適合現在進場」】"
            advice_summary = "是多頭確認與進場位置，也是 K 線橫盤突破，雖然符合進場條件；但因前方存在重大賣壓瑕疵，此時進場勝率不高，極易碰壁拉回！"
        else:
            decision = "🔴【不符合進場條件，建議觀望不買】"
            advice_summary = "當前技術面型態偏弱或架構未完成，切勿逆勢摸底。"
    else:
        if pros and len(pros) >= 2:
            decision = "🟢【符合條件，適合進場】"
            advice_summary = "多頭型態完整、轉折訊號明確，且前方無重大爆量黑K阻礙，可依進場紀律執行操作。"
        else:
            decision = "⚪【條件尚不齊全，放入鎖股池等待】"
            advice_summary = "當前尚未出現明確多頭發動關鍵訊號，建議先列入鎖股池追蹤觀察。"

    return {
        "code": info['code'],
        "name": info['name'],
        "as_of_date": last['Date'].strftime('%Y-%m-%d'),
        "is_replay": is_replay,
        "close": c,
        "open": o,
        "high": h,
        "low": l,
        "volume": int(v),
        "vol_ma20": int(v_ma20),
        "vol_ratio": round(v / v_ma20, 2) if v_ma20 > 0 else 1.0,
        "change": round(c - float(prev['Close']), 2),
        "change_pct": round(((c - float(prev['Close'])) / float(prev['Close'])) * 100, 2),
        "sma5": sma5,
        "sma20": sma20,
        "sma60": sma60,
        "trend_status": trend['trend_status'],
        "support": sup,
        "resistance": res,
        "decision": decision,
        "advice_summary": advice_summary,
        "pros": pros,
        "cons": cons,
        "heavy_black_ks": unresolved_black_ks,
        "is_today_heavy_black": is_today_heavy_black,
        "up_days": up_days,
        "stage": signals_dict.get('watchlist_stage', '觀察中')
    }

def answer_question(user_query: str, stock_context: dict = None, as_of_date: str = None) -> str:
    """
    回答學員問題，具備真實助教之建議性、研判性、純觀念教學與歷史覆盤時光機
    """
    q = user_query.strip()
    
    default_code = stock_context.get('code', '2330') if stock_context else '2330'
    target_code, has_explicit_stock = extract_target_symbol(q, default_code)

    # 1. 若明確指定個股或代號（例如提問中含有 2851、台積電，或明確指稱「這檔」）：
    # 優先執行深度個股技術面診斷與歷史時光機覆盤
    if has_explicit_stock:
        df_ctx = stock_context.get('df') if (stock_context and stock_context.get('code') == target_code) else None
        info_ctx = stock_context.get('info') if (stock_context and stock_context.get('code') == target_code) else None
        diag = diagnose_stock_deeply(target_code, q, as_of_date=as_of_date, df_raw=df_ctx, info=info_ctx)
        if diag:
            response_lines = []
            response_lines.append("### 🧑‍🏫 【技術分析實戰助教 · 實戰解答】")
            if diag['is_replay']:
                response_lines.append(f"> ⏳ **【歷史覆盤時光機 · 診斷基準日：{diag['as_of_date']}】**")
                response_lines.append(f"> *(時光倒流回溯：以 {diag['as_of_date']} 當天盤後收盤視角為您重現技術面與助教決策)*\n")

            response_lines.append(f"針對 **{diag['name']} ({diag['code']})** 在 **{diag['as_of_date']}** 的技術面與進場研判：")
            response_lines.append(f"- **當日收盤價**：{diag['close']:.2f} 元 ({'+' if diag['change']>=0 else ''}{diag['change']:.2f} 元, {'+' if diag['change_pct']>=0 else ''}{diag['change_pct']:.2f}%)")
            response_lines.append(f"- **趨勢架構**：{diag['trend_status']}")
            response_lines.append("")
            response_lines.append("#### 🎯 一、助教核心操作結論：")
            response_lines.append(f"> ### **{diag['decision']}**")
            response_lines.append(f"> **{diag['advice_summary']}**")
            response_lines.append("")

            response_lines.append("#### 🔍 二、條件符合點拆解（型態與位置）：")
            if diag['pros']:
                for p in diag['pros']:
                    response_lines.append(f"- ✅ **{p}**")
            else:
                response_lines.append("- ⚠️ 尚未具備明顯的多頭攻擊條件。")
            response_lines.append("")

            response_lines.append("#### ⚠️ 三、關鍵風險與瑕疵排查（助教叮嚀）：")
            if diag['cons']:
                for c in diag['cons']:
                    response_lines.append(f"- ❌ **{c}**")
            else:
                response_lines.append("- ✅ 前方無重大爆量黑 K 阻礙，且離前高壓力仍有發揮空間，量價結構相對乾淨。")
            response_lines.append("")

            response_lines.append("#### 📋 四、助教給您的後續應對劇本：")
            if diag['is_today_heavy_black']:
                response_lines.append("1. **【絕對觀望不可摸底】**：今日爆出巨量長黑，主力出貨確立，下方支撐均可能被摜破，萬萬不可貪便宜摸底！")
                response_lines.append("2. **【持股防守紀律】**：手中持有者應於跌破 5MA 或虧損達 5% 時嚴格執行停損，保護本金。")
            elif diag['heavy_black_ks']:
                max_bk = max(diag['heavy_black_ks'], key=lambda x: x['high'])
                response_lines.append("1. **【想進場的安全買點】**：")
                response_lines.append(f"   - **化解賣壓才買**：必須等待後續出現中長紅 K 棒，且收盤價「**正式放量站上 {max_bk['date']} 的爆量黑 K 高點 {max_bk['high']:.2f} 元**」，代表主力有決心吃掉上面的套牢籌碼，屆時進場才是安全追隨主力的起漲點！")
                response_lines.append("   - **回測鎖股**：若股價受阻拉回，不要急著去接，先放入鎖股池 **【回檔等上漲】**，等待回測 20MA（月線）量縮有守、再出轉折紅 K 站回 5MA 時再做評估。")
            elif diag['up_days'] >= 3:
                response_lines.append(f"1. **【絕不追高原則】**：目前已連漲 {diag['up_days']} 天，寧可錯過也不追高。先將其放入鎖股池 **【高檔等回檔】**，等待拉回測 5MA 或 20MA 不破前低、重新轉折向上時再行切入。")
            else:
                response_lines.append("1. **【進場操作策略】**：若符合進場條件且進場，請依實戰五步驟設定好紀律，短線目標 5%~8%，達到目標毫不猶豫分批獲利。")

            response_lines.append("2. **【防守與停損點】**：")
            sup_val = diag['support'] if diag['support'] else (diag['close'] * 0.95)
            response_lines.append(f"   - 若已有持股或強烈想進場，短線停損請嚴格設定在 **5MA 操盤線 ({diag['sma5']:.2f} 元)** 或 **波段前低支撐 ({sup_val:.2f} 元)**，一旦跌破多頭架構即告破壞，請果斷停損出場，絕不凹單套牢！")

            for topic, content in COURSE_KNOWLEDGE.items():
                if topic in q:
                    response_lines.append(f"\n---\n📘 **【附錄：課程講義標準規範——{topic}】**\n{content}")
                    break

            return "\n".join(response_lines)
        else:
            return f"抱歉，無法取得股票代號 {target_code} 的行情數據，請確認代號是否正確。"

    # 2. 若為純課程觀念理論提問（未指定個股）：優先精準回答概念
    concept_reply = answer_conceptual_question(q)
    if concept_reply:
        return concept_reply

    # 3. 通用技術分析指導
    return answer_general_ta_question(q)

